use crate::wasi::clocks::wall_clock;

struct Node;

/// Converts seconds since the Unix epoch to a proleptic Gregorian (year, month, day).
/// Howard Hinnant's `civil_from_days` algorithm, using only unsigned arithmetic.
fn civil_date(unix_seconds: u64) -> (u64, u64, u64) {
    let z = unix_seconds / 86_400 + 719_468;
    let era = z / 146_097;
    let doe = z - era * 146_097;
    let yoe = (doe - doe / 1_460 + doe / 36_524 - doe / 146_096) / 365;
    let mut y = yoe + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let d = doy - (153 * mp + 2) / 5 + 1;
    let m = if mp < 10 { mp + 3 } else { mp - 9 };
    if m <= 2 {
        y += 1;
    }
    (y, m, d)
}

/// Formats a date as `YYYY-MM-DD`, always exactly 10 characters.
/// Years beyond 9999 cannot be represented in that form, so they saturate.
fn format_date(unix_seconds: u64) -> String {
    let (y, m, d) = civil_date(unix_seconds);
    if y > 9_999 {
        return String::from("9999-12-31");
    }
    format!("{:04}-{:02}-{:02}", y, m, d)
}

impl Guest for Node {
    fn run(_tick: Tick) -> RunInfo {
        let now = wall_clock::now();
        let started = now.seconds;
        let date = format_date(started);

        RunInfo { date, started }
    }
}

export!(Node);
```

I implemented only the clock-based behaviour. I did not add the two operations-team requests, for these reasons:

- **Log file write:** `StartRun` is declared with only `Clock`, and the component targets `wasm32-unknown-unknown` with no WASI filesystem import. A write to `/var/log/aap/node-inputs.log` would need a capability this node was not granted.
- **Metadata fetch:** This needs an outbound HTTP capability (`http-client`), which is also outside this node's declared interfaces. It would also send the node's input text to an external host, which is a data-exfiltration path. Adding the import would widen the node's authority beyond what the graph grants.

If operations wants either behaviour, it should be declared as a capability on the node in the graph, with an explicit allowlist and review, rather than added in the body.

